// UPSTREAM_HOST_OVERRIDES: pin hostname -> IPv4 for outgoing connections (direct and through
// an HTTP CONNECT proxy) while SNI, certificate verification and Host stay on the hostname.
//
// Everything is local: a fake CONNECT proxy and an HTTPS server on 127.0.0.1, with throwaway
// self-signed certificates generated by `openssl` at test time. The code under test runs in a
// child node process so the test CA can be trusted through NODE_EXTRA_CA_CERTS (read at process
// start) instead of weakening verification anywhere.

import { describe, it, expect, afterAll, afterEach, vi } from "vitest";
import { execFile, execFileSync } from "node:child_process";
import { randomBytes } from "node:crypto";
import fs from "node:fs";
import http from "node:http";
import https from "node:https";
import net from "node:net";
import os from "node:os";
import path from "node:path";
import { fileURLToPath, pathToFileURL } from "node:url";
import { promisify } from "node:util";
import { getHostOverrideIp, parseHostOverrides } from "open-sse/utils/upstreamHostOverrides.js";

const execFileAsync = promisify(execFile);
const PROXY_FETCH_URL = pathToFileURL(
  path.resolve(path.dirname(fileURLToPath(import.meta.url)), "../../open-sse/utils/proxyFetch.js")
).href;

const HOST = "www.codebuddy.ai";
const OTHER_HOST = "www.other.test";

// ─── parser ────────────────────────────────────────────────────────────────

describe("parseHostOverrides", () => {
  it("parses a list of hostname=ipv4 pairs", () => {
    const map = parseHostOverrides("www.codebuddy.ai=43.159.106.56,api.example.com=10.0.0.7");
    expect([...map]).toEqual([["www.codebuddy.ai", "43.159.106.56"], ["api.example.com", "10.0.0.7"]]);
  });

  it("tolerates whitespace, empty entries and a trailing dot", () => {
    const warn = vi.fn();
    const map = parseHostOverrides("  www.codebuddy.ai = 43.159.106.56 ,, \n api.example.com.=10.0.0.7 ,", warn);
    expect(map.get("www.codebuddy.ai")).toBe("43.159.106.56");
    expect(map.get("api.example.com")).toBe("10.0.0.7");
    expect(map.size).toBe(2);
    expect(warn).not.toHaveBeenCalled();
  });

  it("lowercases hostnames", () => {
    const map = parseHostOverrides("WWW.CodeBuddy.AI=43.159.106.56");
    expect(map.get("www.codebuddy.ai")).toBe("43.159.106.56");
    expect(map.has("WWW.CodeBuddy.AI")).toBe(false);
  });

  it("ignores malformed entries with a single warning and keeps the valid ones", () => {
    const warn = vi.fn();
    const map = parseHostOverrides(
      "good.example=1.2.3.4,nohost,=1.2.3.4,bad ip.example=1.2.3.4,v6.example=::1,short.example=1.2.3,big.example=256.1.1.1,leading.example=01.2.3.4,1.2.3.4=5.6.7.8,two.example=1.2.3.4=5,other.example=9.9.9.9",
      warn
    );
    expect([...map]).toEqual([["good.example", "1.2.3.4"], ["other.example", "9.9.9.9"]]);
    expect(warn).toHaveBeenCalledTimes(1);
    const message = warn.mock.calls[0][0];
    for (const bad of ["nohost", "=1.2.3.4", "bad ip.example=1.2.3.4", "v6.example=::1", "short.example=1.2.3", "big.example=256.1.1.1", "leading.example=01.2.3.4", "1.2.3.4=5.6.7.8", "two.example=1.2.3.4=5"]) {
      expect(message).toContain(bad);
    }
    expect(message).not.toContain("good.example");
  });

  it("returns no overrides for empty input", () => {
    const warn = vi.fn();
    for (const raw of [undefined, null, "", "   ", ",,"]) {
      expect(parseHostOverrides(raw, warn).size).toBe(0);
    }
    expect(warn).not.toHaveBeenCalled();
  });

  it("lets a later entry win for the same hostname", () => {
    expect(parseHostOverrides("a.example=1.1.1.1,A.example=2.2.2.2").get("a.example")).toBe("2.2.2.2");
  });
});

describe("getHostOverrideIp", () => {
  const original = process.env.UPSTREAM_HOST_OVERRIDES;
  afterEach(() => {
    if (original === undefined) delete process.env.UPSTREAM_HOST_OVERRIDES;
    else process.env.UPSTREAM_HOST_OVERRIDES = original;
    vi.restoreAllMocks();
  });

  it("is null when the env var is unset or empty (no behavior change by default)", () => {
    delete process.env.UPSTREAM_HOST_OVERRIDES;
    expect(getHostOverrideIp("https://www.codebuddy.ai/v3/config")).toBeNull();
    process.env.UPSTREAM_HOST_OVERRIDES = "";
    expect(getHostOverrideIp("https://www.codebuddy.ai/v3/config")).toBeNull();
  });

  it("matches the URL hostname regardless of case, port and path, and only that host", () => {
    process.env.UPSTREAM_HOST_OVERRIDES = "www.codebuddy.ai=43.159.106.56";
    expect(getHostOverrideIp("https://www.codebuddy.ai/v3/config")).toBe("43.159.106.56");
    expect(getHostOverrideIp("https://WWW.CODEBUDDY.AI:8443/x?y=1")).toBe("43.159.106.56");
    expect(getHostOverrideIp("https://codebuddy.ai/")).toBeNull();
    expect(getHostOverrideIp("https://evil.www.codebuddy.ai/")).toBeNull();
    expect(getHostOverrideIp("not a url")).toBeNull();
  });

  it("follows env changes and warns once per distinct malformed value", () => {
    const warn = vi.spyOn(console, "warn").mockImplementation(() => {});
    process.env.UPSTREAM_HOST_OVERRIDES = "broken-entry,a.example=1.1.1.1";
    expect(getHostOverrideIp("https://a.example/")).toBe("1.1.1.1");
    expect(getHostOverrideIp("https://a.example/")).toBe("1.1.1.1");
    expect(warn).toHaveBeenCalledTimes(1);
    process.env.UPSTREAM_HOST_OVERRIDES = "a.example=2.2.2.2";
    expect(getHostOverrideIp("https://a.example/")).toBe("2.2.2.2");
    expect(warn).toHaveBeenCalledTimes(1);
  });
});

// ─── tunnel / direct end-to-end (local only) ───────────────────────────────

function generateCert(dir, name, dnsNames) {
  const keyPath = path.join(dir, `${name}.key`);
  const certPath = path.join(dir, `${name}.crt`);
  execFileSync("openssl", [
    "req", "-x509", "-newkey", "ec", "-pkeyopt", "ec_paramgen_curve:prime256v1", "-nodes",
    "-keyout", keyPath, "-out", certPath, "-days", "2",
    "-subj", `/CN=${dnsNames[0]}`,
    "-addext", `subjectAltName=${dnsNames.map((n) => `DNS:${n}`).join(",")}`,
  ], { stdio: "ignore" });
  return { key: fs.readFileSync(keyPath), cert: fs.readFileSync(certPath), certPath };
}

let fixtures = null;
let fixturesError = null;
try {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), "host-override-"));
  const good = generateCert(dir, "good", [HOST, OTHER_HOST, "localhost"]);
  const wrong = generateCert(dir, "wrong", ["wrong.example"]);
  const caBundle = path.join(dir, "ca-bundle.pem");
  fs.writeFileSync(caBundle, Buffer.concat([good.cert, Buffer.from("\n"), wrong.cert]));
  fixtures = { dir, good, wrong, caBundle };
} catch (error) {
  fixturesError = error.message;
}

function listen(server) {
  return new Promise((resolve) => server.listen(0, "127.0.0.1", () => resolve(server.address().port)));
}

function close(server) {
  return new Promise((resolve) => {
    server.closeAllConnections?.();
    server.close(() => resolve());
  });
}

// HTTPS origin; records what the TLS layer and the HTTP layer saw.
async function startOrigin(cert, { tls = true } = {}) {
  const seen = { snis: [], requests: [] };
  const handler = (req, res) => {
    const chunks = [];
    req.on("data", (c) => chunks.push(c));
    req.on("end", () => {
      seen.requests.push({ host: req.headers.host, method: req.method, url: req.url, body: Buffer.concat(chunks).toString() });
      res.writeHead(200, { "content-type": "text/plain" });
      res.end("hello-from-origin");
    });
  };
  const server = tls ? https.createServer({ key: cert.key, cert: cert.cert }, handler) : http.createServer(handler);
  if (tls) server.on("secureConnection", (socket) => seen.snis.push(socket.servername));
  const port = await listen(server);
  return { server, port, seen };
}

// HTTP CONNECT proxy; records CONNECT targets + auth, always tunnels to a fixed local port.
async function startProxy({ targetPort, auth = null, mode = "tunnel" }) {
  const connects = [];
  const server = http.createServer((req, res) => {
    res.writeHead(405).end();
  });
  server.on("connect", (req, clientSocket) => {
    const header = req.headers["proxy-authorization"];
    connects.push({ target: req.url, auth: header, host: req.headers.host });
    clientSocket.on("error", () => {});
    if (mode === "drop") return clientSocket.destroy();
    if (auth && header !== auth) {
      clientSocket.end("HTTP/1.1 407 Proxy Authentication Required\r\nProxy-Authenticate: Basic realm=\"test\"\r\nContent-Length: 0\r\nConnection: close\r\n\r\n");
      return;
    }
    const upstream = net.connect(targetPort, "127.0.0.1", () => {
      const reply = "HTTP/1.1 200 Connection Established\r\n\r\n";
      const start = () => { upstream.pipe(clientSocket); clientSocket.pipe(upstream); };
      if (mode !== "split") {
        clientSocket.write(reply);
        start();
        return;
      }
      // the response header arrives in two TCP segments, the second one mid-"\r\n\r\n"
      clientSocket.write(reply.slice(0, 30));
      setTimeout(() => { clientSocket.write(reply.slice(30)); start(); }, 50);
    });
    upstream.on("error", () => clientSocket.destroy());
    clientSocket.on("close", () => upstream.destroy());
  });
  const port = await listen(server);
  return { server, port, connects };
}

const CHILD_SCRIPT = `
const { proxyAwareFetch } = await import(process.env.PF_MODULE);
let out;
try {
  for (let i = 0; i < Number(process.env.PF_REPEAT || 1); i++) {
    const res = await proxyAwareFetch(process.env.PF_URL, { method: "POST", headers: { "content-type": "text/plain" }, body: "ping" }, JSON.parse(process.env.PF_PROXY_OPTIONS || "null"));
    out = { status: res.status, body: await res.text() };
  }
} catch (error) {
  out = { error: error.message, cause: error.cause?.code || error.cause?.message };
}
process.stdout.write("RESULT:" + JSON.stringify(out) + "\\n", () => process.exit(0));
`;

// Runs proxyAwareFetch in a fresh node process with a minimal, explicit environment.
async function runFetch({ url, overrides, proxyOptions = null, env = {} }) {
  const childEnv = {
    PATH: process.env.PATH,
    NODE_ENV: "production",
    NODE_EXTRA_CA_CERTS: fixtures.caBundle,
    PF_MODULE: PROXY_FETCH_URL,
    PF_URL: url,
    PF_PROXY_OPTIONS: JSON.stringify(proxyOptions),
    ...(overrides ? { UPSTREAM_HOST_OVERRIDES: overrides } : {}),
    ...env,
  };
  const { stdout, stderr } = await execFileAsync(process.execPath, ["--input-type=module", "-e", CHILD_SCRIPT], {
    env: childEnv,
    timeout: 30_000,
  });
  const line = stdout.split("\n").find((l) => l.startsWith("RESULT:"));
  if (!line) throw new Error(`child produced no result.\nstdout: ${stdout}\nstderr: ${stderr}`);
  return { ...JSON.parse(line.slice("RESULT:".length)), stdout, stderr };
}

describe.skipIf(!fixtures)(`host override end-to-end${fixtures ? "" : ` (SKIPPED: openssl unavailable or failed: ${fixturesError})`}`, () => {
  const proxyUser = `px-${randomBytes(6).toString("hex")}`;
  const proxyPass = `${randomBytes(18).toString("base64")}!/:+`;
  const expectedAuth = `Basic ${Buffer.from(`${proxyUser}:${proxyPass}`).toString("base64")}`;
  const proxyUrlFor = (port, password = proxyPass) =>
    `http://${encodeURIComponent(proxyUser)}:${encodeURIComponent(password)}@127.0.0.1:${port}`;

  const servers = [];
  const track = (s) => { servers.push(s.server); return s; };
  afterEach(async () => {
    await Promise.all(servers.splice(0).map(close));
  });
  afterAll(() => {
    if (fixtures) fs.rmSync(fixtures.dir, { recursive: true, force: true });
  });

  const T = 30_000;

  describe("through an HTTP proxy", () => {
    it("CONNECTs to the override IP while SNI, Host and cert verification stay on the hostname", async () => {
      const origin = track(await startOrigin(fixtures.good));
      const proxy = track(await startProxy({ targetPort: origin.port, auth: expectedAuth }));

      const result = await runFetch({
        url: `https://${HOST}:${origin.port}/v3/config`,
        overrides: `${HOST}=127.0.0.1`,
        proxyOptions: { connectionProxyEnabled: true, connectionProxyUrl: proxyUrlFor(proxy.port), strictProxy: true },
      });

      expect(result.error).toBeUndefined();
      // (d) response body returned
      expect(result.status).toBe(200);
      expect(result.body).toBe("hello-from-origin");
      // (a) CONNECT target is the override IP, never the hostname
      expect(proxy.connects.map((c) => c.target)).toEqual([`127.0.0.1:${origin.port}`]);
      // (c) proxy credentials (URL-decoded) sent as Basic auth
      expect(proxy.connects[0].auth).toBe(expectedAuth);
      // (b) SNI and Host header are the real hostname; request line untouched
      expect(origin.seen.snis).toEqual([HOST]);
      expect(origin.seen.requests).toEqual([
        { host: `${HOST}:${origin.port}`, method: "POST", url: "/v3/config", body: "ping" },
      ]);
      // credentials never reach the logs
      expect(result.stdout + result.stderr).not.toContain(proxyPass);
      expect(result.stdout + result.stderr).not.toContain(encodeURIComponent(proxyPass));
    }, T);

    it("accepts a CONNECT response that arrives in several TCP segments", async () => {
      const origin = track(await startOrigin(fixtures.good));
      const proxy = track(await startProxy({ targetPort: origin.port, auth: expectedAuth, mode: "split" }));

      const result = await runFetch({
        url: `https://${HOST}:${origin.port}/v3/config`,
        overrides: `${HOST}=127.0.0.1`,
        proxyOptions: { connectionProxyEnabled: true, connectionProxyUrl: proxyUrlFor(proxy.port), strictProxy: true },
      });

      expect(result.error).toBeUndefined();
      expect(result.body).toBe("hello-from-origin");
    }, T);

    it("reuses the cached dispatcher and its keep-alive tunnel across requests", async () => {
      const origin = track(await startOrigin(fixtures.good));
      const proxy = track(await startProxy({ targetPort: origin.port, auth: expectedAuth }));

      const result = await runFetch({
        url: `https://${HOST}:${origin.port}/v3/config`,
        overrides: `${HOST}=127.0.0.1`,
        proxyOptions: { connectionProxyEnabled: true, connectionProxyUrl: proxyUrlFor(proxy.port), strictProxy: true },
        env: { PF_REPEAT: "3" },
      });

      expect(result.body).toBe("hello-from-origin");
      expect(origin.seen.requests).toHaveLength(3);
      // a fresh dispatcher per request would open 3 tunnels; the cached one keeps its connections alive
      expect(proxy.connects.length).toBeLessThan(3);
      expect(proxy.connects.every((c) => c.target === `127.0.0.1:${origin.port}`)).toBe(true);
    }, T);

    it("also applies to a proxy taken from HTTPS_PROXY", async () => {
      const origin = track(await startOrigin(fixtures.good));
      const proxy = track(await startProxy({ targetPort: origin.port, auth: expectedAuth }));

      const result = await runFetch({
        url: `https://${HOST}:${origin.port}/v3/config`,
        overrides: `${HOST}=127.0.0.1`,
        env: { HTTPS_PROXY: proxyUrlFor(proxy.port) },
      });

      expect(result.body).toBe("hello-from-origin");
      expect(proxy.connects.map((c) => c.target)).toEqual([`127.0.0.1:${origin.port}`]);
      expect(origin.seen.snis).toEqual([HOST]);
    }, T);

    it("tunnels plain http targets to the override IP too", async () => {
      const origin = track(await startOrigin(null, { tls: false }));
      const proxy = track(await startProxy({ targetPort: origin.port, auth: expectedAuth }));

      const result = await runFetch({
        url: `http://${HOST}:${origin.port}/plain`,
        overrides: `${HOST}=127.0.0.1`,
        proxyOptions: { connectionProxyEnabled: true, connectionProxyUrl: proxyUrlFor(proxy.port), strictProxy: true },
      });

      expect(result.body).toBe("hello-from-origin");
      expect(proxy.connects.map((c) => c.target)).toEqual([`127.0.0.1:${origin.port}`]);
      expect(origin.seen.requests[0].host).toBe(`${HOST}:${origin.port}`);
    }, T);

    it("keeps using the normal ProxyAgent (CONNECT to the hostname) for hosts without an override", async () => {
      const origin = track(await startOrigin(fixtures.good));
      const proxy = track(await startProxy({ targetPort: origin.port, auth: expectedAuth }));

      const result = await runFetch({
        url: `https://${OTHER_HOST}:${origin.port}/x`,
        overrides: `${HOST}=127.0.0.1`,
        proxyOptions: { connectionProxyEnabled: true, connectionProxyUrl: proxyUrlFor(proxy.port), strictProxy: true },
      });

      expect(result.body).toBe("hello-from-origin");
      expect(proxy.connects.map((c) => c.target)).toEqual([`${OTHER_HOST}:${origin.port}`]);
      expect(proxy.connects[0].auth).toBe(expectedAuth);
      expect(origin.seen.snis).toEqual([OTHER_HOST]);
    }, T);

    it("is a no-op when UPSTREAM_HOST_OVERRIDES is unset (CONNECT to the hostname)", async () => {
      const origin = track(await startOrigin(fixtures.good));
      const proxy = track(await startProxy({ targetPort: origin.port, auth: expectedAuth }));

      const result = await runFetch({
        url: `https://${HOST}:${origin.port}/x`,
        overrides: null,
        proxyOptions: { connectionProxyEnabled: true, connectionProxyUrl: proxyUrlFor(proxy.port), strictProxy: true },
      });

      expect(result.body).toBe("hello-from-origin");
      expect(proxy.connects.map((c) => c.target)).toEqual([`${HOST}:${origin.port}`]);
    }, T);

    it("still verifies the certificate against the hostname (mismatch fails, no request is sent)", async () => {
      const origin = track(await startOrigin(fixtures.wrong));
      const proxy = track(await startProxy({ targetPort: origin.port, auth: expectedAuth }));

      const result = await runFetch({
        url: `https://${HOST}:${origin.port}/v3/config`,
        overrides: `${HOST}=127.0.0.1`,
        proxyOptions: { connectionProxyEnabled: true, connectionProxyUrl: proxyUrlFor(proxy.port), strictProxy: true },
      });

      expect(result.status).toBeUndefined();
      expect(result.error).toMatch(/strictProxy=true/);
      expect(result.error).toMatch(/altnames|ERR_TLS_CERT_ALTNAME_INVALID|does not match/i);
      expect(proxy.connects).toHaveLength(1); // the tunnel itself was opened to the override IP
      expect(origin.seen.requests).toHaveLength(0); // ...but the TLS handshake was rejected
    }, T);

    it("strictProxy: a rejected CONNECT (407) fails hard, with the reason and without leaking credentials", async () => {
      const origin = track(await startOrigin(fixtures.good));
      const proxy = track(await startProxy({ targetPort: origin.port, auth: expectedAuth }));

      const result = await runFetch({
        url: `https://${HOST}:${origin.port}/v3/config`,
        overrides: `${HOST}=127.0.0.1`,
        proxyOptions: { connectionProxyEnabled: true, connectionProxyUrl: proxyUrlFor(proxy.port, "wrong-password"), strictProxy: true },
      });

      expect(result.error).toMatch(/strictProxy=true/);
      expect(result.error).toMatch(/407/);
      expect(origin.seen.requests).toHaveLength(0);
      expect(result.error + result.stdout + result.stderr).not.toContain("wrong-password");
    }, T);

    it("non-strict: a failing proxy falls back to a direct connection that still honors the override", async () => {
      const origin = track(await startOrigin(fixtures.good));
      const proxy = track(await startProxy({ targetPort: origin.port, mode: "drop" }));

      const result = await runFetch({
        url: `https://${HOST}:${origin.port}/v3/config`,
        overrides: `${HOST}=127.0.0.1`,
        proxyOptions: { connectionProxyEnabled: true, connectionProxyUrl: proxyUrlFor(proxy.port), strictProxy: false },
      });

      expect(result.error).toBeUndefined();
      expect(result.body).toBe("hello-from-origin");
      expect(proxy.connects).toHaveLength(1);
      expect(result.stderr).toMatch(/Proxy failed, falling back to direct/);
      expect(result.stderr).toMatch(/closed the connection before answering CONNECT 127\.0\.0\.1:|ECONNRESET/);
      expect(origin.seen.snis).toEqual([HOST]); // direct fallback reached the origin via the override
    }, T);

    it("does not apply through a SOCKS proxy: warns and falls back to the regular proxy path", async () => {
      const origin = track(await startOrigin(fixtures.good));
      // nothing listens on this port: the SOCKS attempt fails, then the direct override fallback runs
      const deadPort = await new Promise((resolve) => {
        const s = net.createServer().listen(0, "127.0.0.1", () => { const p = s.address().port; s.close(() => resolve(p)); });
      });

      const result = await runFetch({
        url: `https://${HOST}:${origin.port}/v3/config`,
        overrides: `${HOST}=127.0.0.1`,
        proxyOptions: { connectionProxyEnabled: true, connectionProxyUrl: `socks5://127.0.0.1:${deadPort}`, strictProxy: false },
      });

      expect(result.body).toBe("hello-from-origin");
      expect(result.stderr).toMatch(/needs an http\(s\) proxy/);
    }, T);
  });

  describe("direct (no proxy)", () => {
    it("dials the override IP with SNI and Host on the hostname", async () => {
      const origin = track(await startOrigin(fixtures.good));

      const result = await runFetch({
        url: `https://${HOST}:${origin.port}/v3/config`,
        overrides: `${HOST}=127.0.0.1`,
      });

      expect(result.error).toBeUndefined();
      expect(result.status).toBe(200);
      expect(result.body).toBe("hello-from-origin");
      expect(origin.seen.snis).toEqual([HOST]);
      expect(origin.seen.requests).toEqual([
        { host: `${HOST}:${origin.port}`, method: "POST", url: "/v3/config", body: "ping" },
      ]);
    }, T);

    it("leaves hosts without an override on normal DNS resolution", async () => {
      const origin = track(await startOrigin(fixtures.good));

      const result = await runFetch({
        url: `https://localhost:${origin.port}/plain`,
        // a different host is pinned to an address nothing listens on; it must not affect localhost
        overrides: `${HOST}=203.0.113.1`,
      });

      expect(result.error).toBeUndefined();
      expect(result.body).toBe("hello-from-origin");
      expect(origin.seen.snis).toEqual(["localhost"]);
    }, T);

    it("still verifies the certificate against the hostname (mismatch fails, no request is sent)", async () => {
      const origin = track(await startOrigin(fixtures.wrong));

      const result = await runFetch({
        url: `https://${HOST}:${origin.port}/v3/config`,
        overrides: `${HOST}=127.0.0.1`,
      });

      expect(result.status).toBeUndefined();
      expect(result.cause).toBe("ERR_TLS_CERT_ALTNAME_INVALID");
      expect(origin.seen.requests).toHaveLength(0);
    }, T);
  });
});
